import {readDOCX} from './docx-import.mjs';
import {googleReady, prepareGoogle, chooseGoogleDocuments, disconnectGoogle, validateGoogleConfig} from './google-import.mjs';
import {documentDrafts, duplicateEntries, sourceURL, importRecord} from './import-tools.mjs';
import {icon, brandDefs, brandMark, contours} from './icons.mjs';
import {STORES, validateBackup, backupPayload, searchScore, reviewDue} from './backup.mjs';
const VERSION='0.6';
const REVISION_LIMIT=25;
// Region names are part of the backup format: keep them stable. Icon key and accent hue are presentation only.
const regionMeta={'Hip':['hip','#527DFF'],'Knee':['knee','#18A999'],'Shoulder':['shoulder','#7C5CFF'],'Spine':['spine','#0EA5E9'],'Ankle & Foot':['foot','#F59E0B'],'Neurological':['neuro','#D946EF'],'Cardiopulmonary':['cardio','#F43F5E'],'Balance & Vestibular':['vestibular','#06B6D4'],'Elbow / Wrist / Hand':['hand','#F97316'],'Other':['other','#64748B']};
const regions=Object.keys(regionMeta);
const categories=['Therapeutic Exercise','Functional Training','Gait Training','Balance Training','Manual Therapy','Neuromuscular Re-education','Patient Education','Other'];
const statuses=[['draft','Draft'],['unreviewed','Needs review'],['reviewed','Reviewed']];
const examples=[['Hip','Total Hip Arthroplasty (THA)'],['Hip','Femoroacetabular Impingement (FAI)'],['Hip','Hip Osteoarthritis'],['Hip','Greater Trochanteric Pain Syndrome'],['Knee','Total Knee Arthroplasty (TKA)'],['Knee','ACL Reconstruction'],['Knee','Patellofemoral Pain'],['Shoulder','Rotator Cuff Pathology'],['Shoulder','Adhesive Capsulitis'],['Spine','Low Back Pain'],['Spine','Cervical Radiculopathy'],['Ankle & Foot','Lateral Ankle Sprain'],['Ankle & Foot','Achilles Tendinopathy'],['Neurological','Stroke Rehabilitation'],['Neurological','Parkinson Disease'],['Cardiopulmonary','COPD'],['Balance & Vestibular','BPPV']];
const conditionTabs=[['overview','Overview'],['precautions','Precautions'],['protocol','Protocols'],['interventions','Interventions'],['evidence','Evidence'],['notes','Notes']];
let pendingProvenance=null;
let importBatch=[],importMetadata={},textFileMetadata={};
let freshDatabase=false;
let links=[],phases=[],collections=[],revisions=[],linkEdit=null,phaseEdit=null,activeCollection='',collectionEditId=null;
let db,items=[],conditions=[],view='home',activeRegion='',activeCondition='',query='',editId=null,notice='',offlineReady=false;
let theme=readSetting('atlas-theme','system'),sidebarCollapsed=readSetting('atlas-sidebar','')==='collapsed',conditionTab='overview',storageInfo={persisted:false,usage:0,quota:0};
let filters=emptyFilters();
function emptyFilters(){return {region:'',category:'',status:'',source:'',favorites:false}}
const statusFilters=[...statuses,['due','Review due']];
function readSetting(key,fallback){try{return localStorage.getItem(key)||fallback}catch{return fallback}}
function writeSetting(key,value){try{localStorage.setItem(key,value)}catch{}}
const $=s=>document.querySelector(s),escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random();
const today=()=>new Date().toISOString().slice(0,10);
const hue=region=>(regionMeta[region]||regionMeta.Other)[1];
const regionIcon=(region,size)=>icon((regionMeta[region]||regionMeta.Other)[0],size);
const plural=(n,word)=>`${n} ${word}${n===1?'':'s'}`;
const statusOf=x=>x.reviewStatus||'draft';
const statusLabel=x=>(statuses.find(([k])=>k===statusOf(x))||statuses[0])[1];
// Schema v1: interventions, conditions. v2 adds condition-intervention links, protocol phases, collections and revisions.
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('pt-atlas-library',2);r.onupgradeneeded=event=>{const d=r.result;if(event.oldVersion<1){freshDatabase=true;d.createObjectStore('interventions',{keyPath:'id'});d.createObjectStore('conditions',{keyPath:'id'})}if(event.oldVersion<2){d.createObjectStore('links',{keyPath:'id'});d.createObjectStore('phases',{keyPath:'id'});d.createObjectStore('collections',{keyPath:'id'});d.createObjectStore('revisions',{keyPath:'id'})}};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('Close other PT Atlas tabs to finish upgrading local storage.'))})}
function all(store){return new Promise((res,rej)=>{const r=db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
function put(store,obj){return new Promise((res,rej)=>{const t=db.transaction(store,'readwrite');t.objectStore(store).put(obj);t.oncomplete=res;t.onerror=()=>rej(t.error)})}
function remove(store,id){return new Promise((res,rej)=>{const t=db.transaction(store,'readwrite');t.objectStore(store).delete(id);t.oncomplete=res;t.onerror=()=>rej(t.error)})}
async function reload(){[items,conditions,links,phases,collections,revisions]=await Promise.all(STORES.map(all));render()}
const conditionById=id=>conditions.find(c=>c.id===id);
const linksFor=interventionId=>links.filter(l=>l.interventionId===interventionId&&conditionById(l.conditionId));
const phasesFor=conditionId=>phases.filter(p=>p.conditionId===conditionId).sort((a,b)=>(a.order||0)-(b.order||0));
const revisionsFor=entityId=>revisions.filter(r=>r.entityId===entityId).sort((a,b)=>b.at.localeCompare(a.at));
// Interventions on a condition: those whose primary condition matches, plus any linked with condition-specific context.
function conditionEntries(c){const map=new Map();for(const x of items)if(x.condition===c.name&&x.region===c.region)map.set(x.id,{x,link:null});for(const l of links)if(l.conditionId===c.id){const x=items.find(i=>i.id===l.interventionId);if(x)map.set(x.id,{x,link:l})}return [...map.values()].sort((a,b)=>a.x.name.localeCompare(b.x.name))}
function addRevision(tx,entityType,record,summary,extra={}){const store=tx.objectStore('revisions');store.put({id:uid(),entityType,entityId:record.id,entityName:record.name,at:new Date().toISOString(),summary,snapshot:JSON.stringify({record,...extra})});for(const old of revisionsFor(record.id).slice(REVISION_LIMIT-1))store.delete(old.id)}
function readSnapshot(revision){try{const value=JSON.parse(revision.snapshot);return value&&typeof value==='object'&&value.record&&typeof value.record==='object'?value:null}catch{return null}}
function setView(v,r='',c=''){view=v;activeRegion=r;activeCondition=c;editId=null;query='';filters=emptyFilters();conditionTab='overview';render();window.scrollTo(0,0)}
function msg(message){
 notice=message;document.querySelector('.notice')?.remove();const node=document.createElement('div');node.className='notice';node.role='status';node.textContent=message;$('#content')?.before(node);
 setTimeout(()=>{if(notice===message){notice='';document.querySelector('.notice')?.remove();}},4000);
}
const btn=(label,action,extra='',glyph='')=>`<button type="button" class="btn ${extra}" data-action="${action}">${glyph?icon(glyph,18):''}${label}</button>`;
const kicker=(text,region)=>`<p class="kicker"${region?` style="--hue:${hue(region)}"`:''}><span class="kicker-mark" aria-hidden="true"></span>${text}</p>`;
function counts(region){return conditions.filter(c=>c.region===region).length}

// ——— Shell ———
const navItems=[['home','home','Home'],['library','library','Library'],['collections','collection','Collections'],['favorites','heart','Favorites'],['import','import','Import'],['settings','settings','Settings']];
function nav(){return navItems.map(([v,i,t])=>`<button class="${view===v?'active':''}" data-nav="${v}" ${view===v?'aria-current="page"':''}>${icon(i)}<span class="nav-label">${t}</span></button>`).join('')}
function networkText(){return navigator.onLine?(offlineReady?'Online · offline ready':'Online · preparing offline cache'):(offlineReady?'Offline · working from cache':'Offline · cache unavailable')}
function storageText(){return storageInfo.persisted?'Saved on this device · protected':'Saved on this device'}
const themeIcon=()=>theme==='light'?'sun':theme==='dark'?'moon':'system';
function header(){return `<header class="topbar"><button type="button" class="iconbtn sidebar-toggle" data-action="toggle-sidebar" aria-label="${sidebarCollapsed?'Expand':'Collapse'} sidebar" aria-expanded="${!sidebarCollapsed}">${icon('sidebar')}</button><div class="mobile-brand">${brandMark(30)}<span>ATLAS</span></div><label class="search">${icon('search',18)}<input id="globalSearch" type="search" placeholder="Search your library…" value="${escapeHTML(query)}" aria-label="Search library" autocomplete="off"><kbd aria-hidden="true">/</kbd></label><div class="status-pills"><span class="pill ${navigator.onLine?'ok':'warn'}" id="netStatus" role="status">${icon('wifi',14)}<span>${networkText()}</span></span><span class="pill" id="storeStatus">${icon('database',14)}<span>${storageText()}</span></span></div><button type="button" class="iconbtn" data-action="cycle-theme" aria-label="Theme: ${theme}. Change theme">${icon(themeIcon())}</button><button type="button" class="btn primary small new-btn" data-action="add" aria-label="New intervention">${icon('plus',16)}<span>New</span></button></header>`}
function sidebar(){return `<aside class="side" aria-label="Primary"><div class="brand">${brandMark(38)}<div class="wordmark"><strong>PT Atlas</strong><small>Clinical knowledge, anywhere.</small></div></div><nav class="nav" aria-label="Sections">${nav()}</nav><div class="side-card"><p>${icon('shield',16)}<span>Personal reference library. Clinician judgment and patient-specific orders govern care.</span></p></div></aside>`}
function tabbar(){return `<nav class="tabbar" aria-label="Sections">${[['home','home','Home'],['library','library','Library'],['editor','plus','Add'],['favorites','heart','Saved'],['settings','settings','Settings']].map(([v,i,t])=>`<button data-nav="${v}" class="${view===v?'active':''} ${v==='editor'?'tab-add':''}" ${view===v?'aria-current="page"':''}>${icon(i,22)}<span>${t}</span></button>`).join('')}</nav>`}

// ——— Cards ———
function regionTiles(){return `<div class="tiles">${regions.map(r=>{const n=items.filter(x=>x.region===r).length;return `<button class="tile" data-region="${escapeHTML(r)}" style="--hue:${hue(r)}"><span class="tile-icon">${regionIcon(r,26)}</span><span class="tile-body"><h3>${escapeHTML(r)}</h3><span class="tile-meta">${plural(counts(r),'condition')} · ${plural(n,'intervention')}</span></span><span class="tile-arrow">${icon('arrow',18)}</span></button>`}).join('')}</div>`}
function hl(text){const safe=escapeHTML(text),q=escapeHTML(query.trim());if(!q)return safe;const i=safe.toLowerCase().indexOf(q.toLowerCase());return i<0?safe:safe.slice(0,i)+'<mark>'+safe.slice(i,i+q.length)+'</mark>'+safe.slice(i+q.length)}
function linkContext(l){const parts=[['Dosage for this condition',l.dosage],['Restrictions for this condition',l.restrictions],['Notes for this condition',l.notes]].filter(([,v])=>v);return parts.length?`<dl class="link-context">${parts.map(([t,v])=>`<div><dt>${t}</dt><dd>${escapeHTML(v)}</dd></div>`).join('')}</dl>`:''}
const fmtDate=iso=>{const d=new Date(iso);return Number.isNaN(d.getTime())?escapeHTML(iso):d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})};
function badges(x){let out='';if(reviewDue(x))out+=`<span class="badge warn">Review due</span>`;if(x.importedAt)out+=`<span class="badge imported">Imported</span>`;if(statusOf(x)==='unreviewed')out+=`<span class="badge warn">Needs review</span>`;else if(statusOf(x)==='reviewed')out+=`<span class="badge ok">${icon('shield',12)}Reviewed</span>`;return out}
function itemCard(x,link=null){return `<article class="row" style="--hue:${hue(x.region)}"><span class="row-icon">${regionIcon(x.region,22)}</span><div class="row-body">${kicker(escapeHTML(x.region||'Uncategorized')+(x.condition?' · '+escapeHTML(x.condition):''),x.region)}<h3>${hl(x.name)}</h3><div class="chips">${x.category?`<span class="chip">${escapeHTML(x.category)}</span>`:''}${x.tags?x.tags.split(',').map(t=>t.trim()).filter(Boolean).slice(0,4).map(t=>`<span class="chip">#${escapeHTML(t)}</span>`).join(''):''}${badges(x)}${link?`<span class="badge imported">${icon('link',12)}Linked</span>`:''}</div>${link?linkContext(link):''}</div><div class="row-actions"><button class="iconbtn fav ${x.favorite?'on':''}" data-fav="${escapeHTML(x.id)}" aria-pressed="${!!x.favorite}" aria-label="${x.favorite?'Remove from':'Add to'} favorites: ${escapeHTML(x.name)}">${icon(x.favorite?'heartFill':'heart')}</button><button class="btn ghost small" data-open="${escapeHTML(x.id)}">View${icon('chevron',16)}</button></div></article>`}
function conditionCard(c){const n=conditionEntries(c).length,ph=phasesFor(c.id).length;return `<button class="row row-link" data-condition="${escapeHTML(c.name)}" data-c-region="${escapeHTML(c.region)}" style="--hue:${hue(c.region)}"><span class="row-icon">${regionIcon(c.region,22)}</span><span class="row-body">${kicker(escapeHTML(c.region),c.region)}<h3>${hl(c.name)}</h3><span class="row-meta">${plural(n,'linked intervention')}${ph?' · '+plural(ph,'protocol phase'):c.protocol?' · Protocol':''}${c.precautions?' · Precautions':''}</span></span><span class="row-chevron">${icon('chevron')}</span></button>`}
const empty=(title,text,action='')=>`<div class="empty"><div class="empty-mark">${brandMark(44,{tile:false})}</div><h3>${title}</h3><p>${text}</p>${action}</div>`;
function sectionHead(title,aside=''){return `<div class="sectionhead"><h2>${title}</h2>${aside}</div>`}

// ——— Filters ———
function applyFilters(list){return list.filter(x=>(!filters.region||x.region===filters.region)&&(!filters.category||x.category===filters.category)&&(!filters.status||(filters.status==='due'?reviewDue(x):statusOf(x)===filters.status))&&(!filters.source||(filters.source==='imported')===!!x.importedAt)&&(!filters.favorites||x.favorite))}
function filterBar(showRegion=true){const select=(key,label,options)=>`<label class="filter"><span>${label}</span><select data-filter="${key}"><option value="">All</option>${options.map(([v,t])=>`<option value="${escapeHTML(v)}" ${filters[key]===v?'selected':''}>${escapeHTML(t)}</option>`).join('')}</select></label>`;return `<div class="filters" role="group" aria-label="Filter interventions">${showRegion?select('region','Region',regions.map(r=>[r,r])):''}${select('category','Type',categories.map(c=>[c,c]))}${select('status','Review',statusFilters)}${select('source','Source',[['imported','Imported'],['authored','Authored here']])}<label class="toggle"><input type="checkbox" data-filter="favorites" ${filters.favorites?'checked':''}><span>Favorites only</span></label></div>`}

// ——— Views ———
function home(){const recent=[...items].sort((a,b)=>(b.updated||'').localeCompare(a.updated||'')).slice(0,5);const unreviewed=items.filter(x=>statusOf(x)==='unreviewed').length;return `<section class="hero"><div class="hero-copy">${kicker('PT Atlas · Your clinical library')}<h1 class="display">Clinical knowledge,<br><span class="grad">anywhere.</span></h1><p class="lede">Every intervention, protocol and precaution you rely on, organized by body region and condition. It stays with you, even offline.</p><div class="actions">${btn('Add intervention','add','primary','plus')}<button type="button" class="link-cta" data-action="library">Explore the library${icon('chevron',16)}</button></div></div><div class="hero-art" aria-hidden="true"><svg class="contours" viewBox="0 0 600 500" preserveAspectRatio="xMidYMid slice">${contours}</svg><div class="hero-mark">${brandMark(168,{tile:false})}</div></div></section><section class="stats" aria-label="Library summary"><div class="stat" style="--hue:#527DFF"><b>${items.length}</b><span>Interventions</span></div><div class="stat" style="--hue:#18A999"><b>${conditions.length}</b><span>Conditions</span></div><div class="stat" style="--hue:#F43F5E"><b>${items.filter(x=>x.favorite).length}</b><span>Favorites</span></div><button type="button" class="stat" data-action="review-queue" style="--hue:#F59E0B"><b>${unreviewed+items.filter(x=>reviewDue(x)).length}</b><span>Need review</span></button></section>${sectionHead('Browse by region.',`<button type="button" class="link-cta" data-action="library">See all${icon('chevron',16)}</button>`)}${regionTiles()}<div class="split"><section>${sectionHead('Latest.')}${recent.length?`<ol class="stream">${recent.map((x,i)=>`<li style="--hue:${hue(x.region)}"><span class="num">${String(i+1).padStart(2,'0')}</span><div>${kicker(escapeHTML(x.region)+(x.condition?' · '+escapeHTML(x.condition):''),x.region)}<button type="button" class="stream-title" data-open="${escapeHTML(x.id)}">${escapeHTML(x.name)}</button><p class="row-meta">Updated ${escapeHTML(x.updated||'—')}${x.category?' · '+escapeHTML(x.category):''}</p></div></li>`).join('')}</ol>`:empty('Your library is ready.','Add your first intervention or bring in existing notes from a document.',`<div class="actions center">${btn('Create your first entry','add','primary')}${btn('Import notes','import','ghost')}</div>`)}</section><aside class="callout">${icon('shield',22)}<h3>Built for your judgment, not instead of it.</h3><p>PT Atlas never generates dosages, restrictions or progression criteria. Everything here is what you write or import and review. Surgical protocols depend on the treating surgeon or provider.</p><p class="row-meta">No accounts. No trackers. Your library lives in this browser. Export backups regularly and never store patient-identifying information.</p></aside></div>`}
function library(){if(activeRegion)filters.region=activeRegion;const matches=conditions.filter(c=>!activeRegion||c.region===activeRegion).sort((a,b)=>a.name.localeCompare(b.name));const entries=applyFilters(items).sort((a,b)=>a.name.localeCompare(b.name));const head=activeRegion?`<div class="page-head region-head" style="--hue:${hue(activeRegion)}"><nav class="breadcrumb" aria-label="Breadcrumb"><button data-nav="library">Library</button>${icon('chevron',14)}<span>${escapeHTML(activeRegion)}</span></nav><div class="region-title"><span class="tile-icon big">${regionIcon(activeRegion,34)}</span><div>${kicker('Body region',activeRegion)}<h1>${escapeHTML(activeRegion)}</h1></div></div>`:`<div class="page-head">${kicker('Explore')}<h1>Your library</h1><p class="lede small">Browse by body region, open a condition, or filter every intervention you’ve saved.</p>`;return `${head}<div class="actions">${btn('Add intervention','add','primary','plus')}${btn('Add condition','add-condition','ghost','plus')}${!activeRegion?btn('Collections','collections','ghost','collection'):''}${activeRegion?btn('All regions','all-regions','ghost','back'):''}</div></div>${!activeRegion?`${sectionHead('Body regions.')}${regionTiles()}`:''}${sectionHead('Conditions.',`<span class="count">${matches.length}</span>`)}<div class="list">${matches.length?matches.map(conditionCard).join(''):empty('No conditions here yet.','Add a condition to start organizing this region.')}</div>${sectionHead('Interventions.',`<span class="count">${entries.length}</span>`)}${filterBar(!activeRegion)}<div class="list">${entries.length?entries.map(x=>itemCard(x)).join(''):empty('No interventions match.','Add an intervention or adjust the filters.')}</div>`}
function tabContent(c,entries){
 const text=(value,placeholder)=>value?`<div class="prose">${escapeHTML(value)}</div>`:`<p class="placeholder">${placeholder}</p>`;
 switch(conditionTab){
  case 'precautions':return `<div class="warning">${icon('alert',18)}<span>Always verify patient-specific orders, procedure details and the current source protocol. Notes in this personal library are not independently clinically verified.</span></div>${text(c.precautions,'No precautions or contraindications entered yet. Use Edit condition to add them from your source.')}`;
  case 'protocol':{const list=phasesFor(c.id);return `<div class="warning info">${icon('doc',18)}<span>Rehabilitation phases, restrictions and progression criteria for surgical conditions depend on the treating surgeon’s or provider’s protocol. Record the source and date with each phase.</span></div><div class="phase-head"><h3>${icon('phases',18)} Phases</h3>${btn('Add phase','add-phase','ghost small','plus')}</div>${list.length?`<ol class="phases">${list.map((ph,i)=>phaseCard(ph,i,list.length)).join('')}</ol>`:'<p class="placeholder">No structured phases yet. Add phases with objectives, restrictions, criteria to progress and source.</p>'}${c.protocol?`<h3 class="subhead">Protocol notes</h3><div class="prose">${escapeHTML(c.protocol)}</div>`:''}`}
  case 'interventions':return `<div class="list">${entries.length?entries.map(e=>itemCard(e.x,e.link)).join(''):empty('No interventions linked yet.','Add an intervention and set this condition to link it.')}</div>`;
  case 'evidence':return text(c.source,'No evidence or references recorded yet. Add citations or source links with Edit condition.');
  case 'notes':return text(c.notes,'No personal notes yet.');
  default:return `${text(c.overview,'Add a clinical overview for this condition.')}<dl class="facts"><div><dt>Linked interventions</dt><dd>${entries.length}</dd></div><div><dt>Precautions</dt><dd>${c.precautions?'Documented':'Not yet'}</dd></div><div><dt>Protocol</dt><dd>${c.protocol||phasesFor(c.id).length?'Documented':'Not yet'}</dd></div><div><dt>Protocol phases</dt><dd>${phasesFor(c.id).length}</dd></div><div><dt>Last updated</dt><dd>${escapeHTML(c.updated||'—')}</dd></div></dl>${historyPanel(c.id)}`;
 }
}
function conditionPage(){const c=conditions.find(x=>x.name===activeCondition&&x.region===activeRegion);if(!c)return library();const entries=conditionEntries(c);const tab=conditionTabs.find(([k])=>k===conditionTab)||conditionTabs[0];return `<div class="page-head region-head" style="--hue:${hue(c.region)}"><nav class="breadcrumb" aria-label="Breadcrumb"><button data-nav="library">Library</button>${icon('chevron',14)}<button data-region="${escapeHTML(c.region)}">${escapeHTML(c.region)}</button>${icon('chevron',14)}<span>${escapeHTML(c.name)}</span></nav>${kicker('Clinical reference',c.region)}<h1>${escapeHTML(c.name)}</h1><div class="actions">${btn('Add intervention','add','primary','plus')}${btn('Edit condition','edit-condition','ghost','edit')}</div></div><div class="segmented" role="tablist" aria-label="Condition sections">${conditionTabs.map(([k,label])=>`<button type="button" role="tab" id="tab-${k}" data-tab="${k}" aria-selected="${k===tab[0]}" aria-controls="tabpanel" tabindex="${k===tab[0]?0:-1}">${label}${k==='interventions'?` <span class="tab-count">${entries.length}</span>`:''}</button>`).join('')}</div><section class="panel tabpanel" role="tabpanel" id="tabpanel" aria-labelledby="tab-${tab[0]}" tabindex="0"><h2 class="sr-only">${tab[1]}</h2>${tabContent(c,entries)}</section>`}
function detail(){const x=items.find(i=>i.id===editId);if(!x)return library();const sections=[['Clinical purpose',x.purpose],['Setup & positioning',x.setup],['Instructions',x.instructions],['Dosage',x.dosage],['Equipment',x.equipment],['Progressions & regressions',x.progressions],['Precautions & contraindications',x.precautions],['Evidence & references',x.source],['Personal notes',x.notes]];const history=readImportHistory(x.importHistory);return `<div class="page-head region-head" style="--hue:${hue(x.region)}"><nav class="breadcrumb" aria-label="Breadcrumb"><button data-nav="library">Library</button>${icon('chevron',14)}<button data-region="${escapeHTML(x.region)}">${escapeHTML(x.region)}</button>${icon('chevron',14)}<span>${escapeHTML(x.name)}</span></nav>${kicker('Intervention · '+escapeHTML(x.category||'Uncategorized'),x.region)}<h1>${escapeHTML(x.name)}</h1><div class="chips">${badges(x)}</div><div class="actions">${btn('Edit intervention','edit','primary','edit')}<button type="button" class="btn ghost ${x.favorite?'fav-on':''}" data-action="favorite-detail" aria-pressed="${!!x.favorite}">${icon(x.favorite?'heartFill':'heart',18)}${x.favorite?'Favorited':'Favorite'}</button>${btn('Delete','delete','danger','trash')}</div></div><div class="detail"><div class="detail-main">${sections.filter(([,v])=>v).map(([h,v],i)=>`<section class="panel numbered"><span class="num">${String(i+1).padStart(2,'0')}</span><div><h2>${h}</h2><div class="prose">${escapeHTML(v)}</div></div></section>`).join('')}${sections.some(([,v])=>!v)?`<section class="panel undocumented"><h2>Not yet documented</h2><ul>${sections.filter(([,v])=>!v).map(([h])=>`<li>${h}</li>`).join('')}</ul><button type="button" class="link-cta" data-action="edit">Add details${icon('chevron',16)}</button></section>`:''}${historyPanel(x.id)}</div><aside class="detail-side"><div class="panel glance"><h2>At a glance</h2><dl><div><dt>Region</dt><dd>${escapeHTML(x.region)}</dd></div><div><dt>Condition</dt><dd>${x.condition?`<button type="button" class="linkish" data-condition="${escapeHTML(x.condition)}" data-c-region="${escapeHTML(x.region)}">${escapeHTML(x.condition)}</button>`:'General'}</dd></div><div><dt>Type</dt><dd>${escapeHTML(x.category||'—')}</dd></div><div><dt>Review status</dt><dd>${statusLabel(x)}${x.reviewedAt?' · '+escapeHTML(x.reviewedAt):''}</dd></div><div><dt>Author</dt><dd>${escapeHTML(x.author||'—')}</dd></div><div><dt>Last updated</dt><dd>${escapeHTML(x.updated||'Unknown')}</dd></div>${x.tags?`<div><dt>Tags</dt><dd>${escapeHTML(x.tags)}</dd></div>`:''}</dl></div>${linkPanel(x)}${collectionPanel(x)}${x.importedAt||x.importHistory?`<div class="panel glance provenance"><h2>Import provenance</h2><p>Review status: ${escapeHTML(x.reviewStatus||'unreviewed')} · Imported ${escapeHTML(x.importedAt)}<br>Document: ${escapeHTML(x.sourceTitle)}<br>File: ${escapeHTML(x.sourceFile||'Pasted text')}<br>Source modified: ${escapeHTML(x.sourceModifiedAt||'Not supplied')}</p>${history.map(entry=>`<p>Merged document: ${escapeHTML(entry.documentTitle)} · ${escapeHTML(entry.source||entry.fileName||'Pasted text')} · Imported ${escapeHTML(entry.importedAt)} · Source modified ${escapeHTML(entry.fileModifiedAt||'Not supplied')}</p>`).join('')}</div>`:''}<p class="fineprint">Source information is user-provided and unverified.</p></aside></div>`}
function field(name,label,value,{type='textarea',hint='',required=false,placeholder=''}={}){const control=type==='textarea'?`<textarea name="${name}" placeholder="${escapeHTML(placeholder)}">${escapeHTML(value)}</textarea>`:`<input name="${name}" type="${type}" value="${escapeHTML(value)}" placeholder="${escapeHTML(placeholder)}" ${required?'required':''} maxlength="400">`;return `<div class="field"><label>${label}</label>${control}${hint?`<small>${hint}</small>`:''}</div>`}
function editor(){const x=items.find(i=>i.id===editId)||{};const status=x.reviewStatus||(pendingProvenance?'unreviewed':'draft');return `<div class="page-head">${kicker('Your library')}<h1>${x.id?'Edit':'New'} intervention</h1><p class="lede small">Build a reusable, searchable entry. Every field is yours to write and can be updated anytime.</p></div><form class="form" id="interventionForm"><fieldset class="panel"><legend>Basics</legend><div class="field"><label for="name">Intervention name *</label><input id="name" name="name" required maxlength="160" value="${escapeHTML(x.name)}" placeholder="e.g. Sit-to-stand training"></div><div class="two"><div class="field"><label for="region">Body region *</label><select id="region" name="region" required>${regions.map(r=>`<option ${r===(x.region||activeRegion)?'selected':''}>${escapeHTML(r)}</option>`).join('')}</select></div><div class="field"><label for="condition">Condition</label><input id="condition" name="condition" list="conditionOptions" value="${escapeHTML(x.condition||activeCondition)}" placeholder="Optional diagnosis"><datalist id="conditionOptions">${conditions.map(c=>`<option value="${escapeHTML(c.name)}">`).join('')}</datalist></div></div><div class="two"><div class="field"><label>Intervention type</label><select name="category">${categories.map(s=>`<option ${x.category===s?'selected':''}>${s}</option>`).join('')}</select></div>${field('tags','Tags (comma-separated)',x.tags,{type:'text',placeholder:'strength, early rehab'})}</div></fieldset><fieldset class="panel"><legend>Clinical content</legend>${[['purpose','Clinical purpose / target impairment'],['setup','Setup & positioning'],['instructions','Instructions / technique'],['dosage','Dosage / frequency','Enter dosage from your own source. PT Atlas never suggests defaults.'],['equipment','Equipment'],['progressions','Progressions & regressions'],['precautions','Precautions & contraindications']].map(([k,label,hint])=>field(k,label,x[k],{hint,placeholder:'Add '+label.toLowerCase()+'…'})).join('')}</fieldset><fieldset class="panel"><legend>Evidence & review</legend>${field('source','Evidence / source links',x.source,{placeholder:'Citations, guideline names, URLs…'})}<div class="two">${field('author','Author',x.author,{type:'text',placeholder:'Who wrote or verified this entry'})}<div class="field"><label>Review status</label><select name="reviewStatus">${statuses.map(([k,t])=>`<option value="${k}" ${k===status?'selected':''}>${t}</option>`).join('')}</select></div></div>${field('reviewedAt','Last reviewed',x.reviewedAt,{type:'date'})}</fieldset><fieldset class="panel"><legend>Notes</legend>${field('notes','Personal clinical notes',x.notes,{placeholder:'Anything you want to remember…'})}</fieldset><div class="actions sticky-actions"><button class="btn primary" type="submit">Save intervention</button>${btn('Cancel','cancel','ghost')}</div></form>`}
function conditionEditor(){const c=conditions.find(x=>x.name===activeCondition&&x.region===activeRegion)||{};return `<div class="page-head">${kicker('Clinical organization')}<h1>${c.id?'Edit':'New'} condition</h1><p class="lede small">Conditions are organizational labels. Write content from your own verified sources.</p></div><form class="form" id="conditionForm"><fieldset class="panel"><legend>Basics</legend><div class="field"><label>Condition name *</label><input name="name" required maxlength="160" value="${escapeHTML(c.name)}" placeholder="e.g. Total Hip Arthroplasty"></div><div class="field"><label>Body region</label><select name="region">${regions.map(r=>`<option ${r===(c.region||activeRegion)?'selected':''}>${escapeHTML(r)}</option>`).join('')}</select></div></fieldset><fieldset class="panel"><legend>Reference content</legend>${[['overview','Clinical overview'],['precautions','Precautions / contraindications'],['protocol','Protocols / rehabilitation phases','For each phase: objectives, restrictions, criteria to progress, source and date. Surgical protocols follow the treating provider.'],['source','Evidence / references'],['notes','Personal notes']].map(([k,l,hint])=>field(k,l,c[k],{hint})).join('')}</fieldset><div class="actions sticky-actions"><button class="btn primary" type="submit">Save condition</button>${btn('Cancel','cancel','ghost')}${c.id?btn('Delete condition','delete-condition','danger','trash'):''}</div></form>`}
function importer(){return `<div class="page-head">${kicker('Bring your knowledge')}<h1>Import your notes.</h1><p class="lede small">Paste text or load a document. Everything opens in a review step first, and nothing is saved until you confirm. No clinical facts are inferred.</p></div><div class="import-grid"><div class="panel"><h2>${icon('doc',20)} Documents & pasted text</h2><p class="muted">Open a Google Doc, copy its contents and paste below, or load a local .txt, .md or .docx file. The first nonempty line becomes the suggested title.</p><div class="form"><div class="field"><label for="textFile">Load a text, Markdown, or DOCX file</label><input type="file" id="textFile" accept=".txt,.md,.docx,text/plain,text/markdown,application/vnd.openxmlformats-officedocument.wordprocessingml.document"></div><p id="fileStatus" class="muted" role="status" aria-live="polite"></p><div class="two"><div class="field"><label>Document title (optional)</label><input id="importTitle" placeholder="e.g. Hip intervention notes"></div><div class="field"><label>Source link (optional)</label><input id="importSource" placeholder="https://docs.google.com/document/d/..."></div></div><div class="field"><label>Paste document text *</label><textarea id="importText" class="tall" placeholder="Paste text from Google Docs here..."></textarea></div><label class="toggle"><input type="checkbox" id="splitSections"><span>Split Markdown level 1–2 headings into separate entries</span></label><div class="actions">${btn('Review as new intervention','review-import','primary')}${btn('Review batch import','review-batch','ghost')}</div></div></div>${googleImportPanel()}<div class="panel"><h2>${icon('download',20)} Restore PT Atlas JSON</h2><p class="muted">Import an exported backup (version 1 or 2). You’ll see how many records are added or replaced before anything changes. Entries with matching IDs are updated; others remain.</p><label class="filepick"><input type="file" id="restoreFile" accept=".json,application/json" aria-label="Select PT Atlas JSON backup"></label></div></div>`}
function fmtBytes(n){if(!n)return '0 MB';const mb=n/1048576;return mb<1?Math.max(1,Math.round(n/1024))+' KB':mb<1024?mb.toFixed(1)+' MB':(mb/1024).toFixed(1)+' GB'}
function settings(){const pct=storageInfo.quota?Math.min(100,storageInfo.usage/storageInfo.quota*100):0;return `<div class="page-head">${kicker('Preferences')}<h1>Settings</h1></div><div class="settings"><section class="panel"><h2>Appearance</h2><p class="muted">Match your device or choose a look for your clinical workspace.</p><div class="segmented compact" role="group" aria-label="Theme">${[['system','System','system'],['light','Light','sun'],['dark','Dark','moon']].map(([k,t,i])=>`<button type="button" data-action="theme-${k}" aria-pressed="${theme===k}">${icon(i,16)}${t}</button>`).join('')}</div></section><section class="panel"><h2>Your data</h2><p class="muted">Your library is stored locally in this browser using IndexedDB. No account or cloud sync is configured. Export backups regularly and do not store patient-identifying data.</p><div class="meter" role="img" aria-label="Storage used ${fmtBytes(storageInfo.usage)} of ${fmtBytes(storageInfo.quota)}"><span style="width:${pct.toFixed(1)}%"></span></div><p class="row-meta" id="storageDetail">${storageInfo.quota?`${fmtBytes(storageInfo.usage)} used of ${fmtBytes(storageInfo.quota)} available to this site.`:'Storage estimate unavailable in this browser.'} ${storageInfo.persisted?'Storage is marked persistent: the browser will not clear it automatically.':'Storage is best-effort: the browser may clear it under storage pressure.'}</p><div class="actions">${btn('Export JSON backup','export','primary','download')}${btn('Open importer','import','ghost','import')}${storageInfo.persisted?'':btn('Protect local data','persist','ghost','shield')}</div></section>${recentlyDeleted()}<section class="panel"><h2>Offline access</h2><p class="muted">${'serviceWorker' in navigator?(offlineReady?'The app shell is cached. PT Atlas opens and works without a connection on this device.':'The app shell is cached after the first successful visit over HTTPS or localhost.'):'This browser does not support service workers.'} Data remains in browser storage unless it is cleared.</p></section><section class="panel about"><div class="about-brand">${brandMark(56)}<div><h2>PT Atlas</h2><p class="row-meta">Version ${VERSION} · Local-first clinical library</p></div></div><p class="muted">This is not medical advice or a prescribing tool. Clinical content is user-entered and should be verified against authoritative sources and patient-specific instructions.</p></section></div>`}
function favorites(){const list=items.filter(x=>x.favorite);return `<div class="page-head">${kicker('Quick access')}<h1>Your favorites</h1><p class="lede small">The interventions you reach for most.</p></div><div class="list">${list.map(x=>itemCard(x)).join('')||empty('Nothing saved yet.','Tap the heart on any intervention to keep it here.')}</div>`}
function searchResults(){const q=query.trim().toLowerCase();const has=v=>typeof v==='string'&&v.toLowerCase().includes(q);const rank=(list,extra)=>list.map(x=>[x,searchScore(x,q)+(extra(x)?1:0)]).filter(([,n])=>n>0).sort((a,b)=>b[1]-a[1]||a[0].name.localeCompare(b[0].name)).map(([x])=>x);const found=applyFilters(rank(items,x=>linksFor(x.id).some(l=>has(l.dosage)||has(l.restrictions)||has(l.notes))));const cs=rank(conditions.filter(c=>!filters.region||c.region===filters.region),c=>phasesFor(c.id).some(ph=>Object.values(ph).some(has)));return `<div class="page-head">${kicker('Search')}<h1>Results for “${escapeHTML(query)}”</h1><p class="lede small">${plural(found.length+cs.length,'result')} across titles, conditions, regions, tags, notes, condition links and protocol phases. Best matches first.</p></div>${filterBar()}${sectionHead('Conditions.',`<span class="count">${cs.length}</span>`)}<div class="list">${cs.map(conditionCard).join('')||'<div class="empty slim">No matching conditions.</div>'}</div>${sectionHead('Interventions.',`<span class="count">${found.length}</span>`)}<div class="list">${found.map(x=>itemCard(x)).join('')||'<div class="empty slim">No matching interventions.</div>'}</div>`}
// Hash routes keep refresh, back/forward and shared links working on GitHub Pages without a server fallback.
function routeHash(){const e=encodeURIComponent;if(query.trim())return null;if(view==='home')return '#/';if(view==='library')return activeRegion?'#/region/'+e(activeRegion):'#/library';if(view==='condition')return '#/condition/'+e(activeRegion)+'/'+e(activeCondition);if(view==='detail')return '#/intervention/'+e(editId);if(['favorites','import','settings','collections'].includes(view))return '#/'+view;if(view==='collection')return '#/collection/'+e(activeCollection);return null}
function applyRoute(){const [name,...rest]=location.hash.replace(/^#\/?/,'').split('/').map(part=>{try{return decodeURIComponent(part)}catch{return ''}});view='home';activeRegion='';activeCondition='';editId=null;query='';filters=emptyFilters();conditionTab='overview';
 if(name==='library')view='library';else if(name==='region'&&regions.includes(rest[0])){view='library';activeRegion=rest[0]}else if(name==='condition'&&rest.length===2){view='condition';[activeRegion,activeCondition]=rest}else if(name==='intervention'&&rest[0]){view='detail';editId=rest[0]}else if(name==='collection'&&rest[0]){view='collection';activeCollection=rest[0]}else if(['favorites','import','settings','collections'].includes(name))view=name}
function syncRoute(){const hash=routeHash();if(hash&&hash!==(location.hash||'#/'))history.pushState(null,'',hash)}
function applyTheme(){const dark=theme==='dark'||(theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';document.querySelector('meta[name="theme-color"]')?.setAttribute('content',dark?'#0B111C':'#F7F9FC')}
function render(){applyTheme();syncRoute();let content=query.trim()?searchResults():view==='home'?home():view==='library'?library():view==='condition'?conditionPage():view==='detail'?detail():view==='editor'?editor():view==='condition-editor'?conditionEditor():view==='favorites'?favorites():view==='collections'?collectionsView():view==='collection'?collectionPage():view==='collection-editor'?collectionEditor():view==='link-editor'?linkEditor():view==='phase-editor'?phaseEditor():view==='import-review'?importReview():view==='import'?importer():settings();$('#app').innerHTML=`${brandDefs()}<a class="skip" href="#content">Skip to content</a><div class="shell ${sidebarCollapsed?'collapsed':''}">${sidebar()}<div class="stage">${header()}<main class="main" id="main">${notice?`<div class="notice" role="status">${escapeHTML(notice)}</div>`:''}<div id="content" tabindex="-1">${content}</div><footer class="footer"><span>${brandMark(20)} PT Atlas</span><p>A personal reference library, not a substitute for professional judgment or patient-specific orders. No patient-identifying information.</p></footer></main></div></div>${tabbar()}`;document.querySelectorAll('.field').forEach((field,index)=>{const label=field.querySelector('label'),input=field.querySelector('input,select,textarea');if(label&&input){input.id=input.id||'field-'+index;label.htmlFor=input.id}})}
async function saveIntervention(form){const data=Object.fromEntries(new FormData(form).entries());if(data.reviewStatus==='reviewed'&&!data.reviewedAt)data.reviewedAt=today();const old=items.find(x=>x.id===editId);const obj={...old,...(old?{}:pendingProvenance||{}),...data,id:old?.id||uid(),favorite:old?.favorite||false,updated:today()};const tx=db.transaction(['interventions','revisions'],'readwrite');if(old)addRevision(tx,'intervention',old,'Edited');tx.objectStore('interventions').put(obj);await transactionDone(tx);pendingProvenance=null;editId=obj.id;view='detail';await reload();msg('Intervention saved locally')}
async function saveCondition(form){const data=Object.fromEntries(new FormData(form).entries());const old=conditions.find(x=>x.name===activeCondition&&x.region===activeRegion);const obj={...old,...data,id:old?.id||uid(),updated:today()};if(conditions.some(c=>c.id!==obj.id&&c.name===obj.name&&c.region===obj.region))throw Error('A condition with this name already exists in this region');
const tx=db.transaction(['conditions','interventions','revisions'],'readwrite');if(old)addRevision(tx,'condition',old,'Edited');tx.objectStore('conditions').put(obj);if(old)for(const item of items.filter(i=>i.region===old.region&&i.condition===old.name))tx.objectStore('interventions').put({...item,region:obj.region,condition:obj.name});await transactionDone(tx);activeRegion=obj.region;activeCondition=obj.name;view='condition';await reload();msg('Condition saved locally')}
function download(text,name){const blob=new Blob([text],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function transactionDone(tx){return new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Storage transaction aborted'))})}
async function restore(file){if(!file)return;try{if(file.size>10e6)throw Error('File is too large (10 MB limit)');const obj=validateBackup(JSON.parse(await file.text()),regions);const current={interventions:items,conditions,links,phases,collections,revisions};const replacements=STORES.reduce((n,store)=>n+obj[store].filter(x=>current[store].some(c=>c.id===x.id)).length,0);
 // A condition with the same name and region but a different ID would duplicate it. Empty starter conditions are replaced; anything with content is a conflict.
 const isEmpty=c=>!['overview','precautions','protocol','source','notes'].some(k=>c[k])&&!phases.some(ph=>ph.conditionId===c.id)&&!links.some(l=>l.conditionId===c.id);
 const clashes=obj.conditions.flatMap(inc=>conditions.filter(c=>c.id!==inc.id&&c.name===inc.name&&c.region===inc.region&&!obj.conditions.some(o=>o.id===c.id)));
 const conflicts=clashes.filter(c=>!isEmpty(c));if(conflicts.length)throw Error('These conditions already exist with different content: '+conflicts.map(c=>c.name).join(', ')+'. Rename or delete them first.');
 if(!confirm(`Import ${obj.interventions.length} interventions, ${obj.conditions.length} conditions, ${obj.phases.length} protocol phases, ${obj.links.length} condition links and ${obj.collections.length} collections? ${replacements} existing records will be replaced; other records will remain.`))return;
 const tx=db.transaction(STORES,'readwrite');for(const c of clashes)tx.objectStore('conditions').delete(c.id);for(const store of STORES)for(const entry of obj[store])tx.objectStore(store).put(entry);await transactionDone(tx);await reload();msg('Backup imported successfully')
 }catch(e){alert('Import failed: '+e.message)}}
async function refreshStorage(){try{const [estimate,persisted]=await Promise.all([navigator.storage?.estimate?.(),navigator.storage?.persisted?.()]);storageInfo={persisted:!!persisted,usage:estimate?.usage||0,quota:estimate?.quota||0}}catch{}const pill=$('#storeStatus span');if(pill)pill.textContent=storageText();if(view==='settings'&&!query.trim())render()}
function updateNetworkStatus(){const pill=$('#netStatus');if(!pill)return;pill.className='pill '+(navigator.onLine?'ok':'warn');pill.querySelector('span').textContent=networkText()}
function selectTab(key,focus){conditionTab=key;render();if(focus)$('#tab-'+key)?.focus()}

document.addEventListener('input',e=>{if(e.target.id==='globalSearch'){const pos=e.target.selectionStart;query=e.target.value;render();const input=$('#globalSearch');input.focus();input.setSelectionRange(pos,pos)}});
document.addEventListener('keydown',e=>{
 const typing=/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)||e.target.isContentEditable;
 if((e.key==='/'&&!typing)||(e.key.toLowerCase()==='k'&&(e.metaKey||e.ctrlKey))){e.preventDefault();$('#globalSearch')?.focus();return}
 if(e.key==='Escape'&&e.target.id==='globalSearch'&&query){query='';render();$('#globalSearch').focus();return}
 if(e.target.getAttribute?.('role')==='tab'){const keys=conditionTabs.map(([k])=>k),i=keys.indexOf(conditionTab);const next={ArrowRight:(i+1)%keys.length,ArrowLeft:(i-1+keys.length)%keys.length,Home:0,End:keys.length-1}[e.key];if(next!==undefined){e.preventDefault();selectTab(keys[next],true)}}
});
document.addEventListener('change',async e=>{
 if(e.target.dataset.filter){const key=e.target.dataset.filter;filters[key]=key==='favorites'?e.target.checked:e.target.value;const focusKey=key;render();document.querySelector(`[data-filter="${focusKey}"]`)?.focus();return}
 if(e.target.id==='restoreFile')restore(e.target.files[0]);
 if(e.target.id==='textFile'){
  const file=e.target.files[0],input=e.target;if(!file)return;
  try{
   if(file.size>5e6)throw Error('File is too large (5 MB limit)');
   if(!/\.(txt|md|docx)$/i.test(file.name))throw Error('Choose a .txt, .md, or .docx file.');
   input.disabled=true;
   const text=/\.docx$/i.test(file.name)?await readDOCX(file):await file.text();
   if(!input.isConnected)return;
   textFileMetadata={fileName:file.name,fileModifiedAt:new Date(file.lastModified).toISOString(),sourceType:/\.docx$/i.test(file.name)?'docx':'text-file'};
   $('#importText').value=text;$('#importTitle').value=file.name.replace(/\.(txt|md|docx)$/i,'');$('#importSource').value='';
   $('#fileStatus').textContent=/\.docx$/i.test(file.name)?'DOCX text extracted locally. Review headings, lists, and tables. Images, comments, footnotes, exact numbering, and formatting are not imported.':'Text loaded. Review before saving.';
  }catch(error){if(input.isConnected){textFileMetadata={};$('#importText').value='';$('#importTitle').value='';$('#fileStatus').textContent='Import failed: '+error.message;}}
  finally{if(input.isConnected)input.disabled=false;}
 }
});
document.addEventListener('submit',async e=>{try{if(e.target.id==='interventionForm'){e.preventDefault();await saveIntervention(e.target)}if(e.target.id==='conditionForm'){e.preventDefault();await saveCondition(e.target)}if(e.target.id==='linkForm'){e.preventDefault();await saveLink(e.target)}if(e.target.id==='phaseForm'){e.preventDefault();await savePhase(e.target)}if(e.target.id==='collectionForm'){e.preventDefault();await saveCollection(e.target)}}catch(err){alert('Save failed: '+err.message)}});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-nav],[data-action],[data-region],[data-condition],[data-open],[data-fav],[data-tab],[data-collection]');if(!el)return;if(el.dataset.tab){selectTab(el.dataset.tab);return}if(el.dataset.collection){activeCollection=el.dataset.collection;setView('collection');return}if(el.dataset.nav){if(el.dataset.nav==='editor'){pendingProvenance=null;editId=null;view='editor';render();window.scrollTo(0,0)}else setView(el.dataset.nav);return}if(el.dataset.region){setView('library',el.dataset.region);return}if(el.dataset.condition){setView('condition',el.dataset.cRegion,el.dataset.condition);return}if(el.dataset.open){editId=el.dataset.open;view='detail';query='';render();window.scrollTo(0,0);return}if(el.dataset.fav){const x=items.find(i=>i.id===el.dataset.fav);if(x){x.favorite=!x.favorite;await put('interventions',x);await reload()}return}const a=el.dataset.action;if(!a)return;try{if(await knowledgeAction(a,el))return}catch(err){alert(err.message);return}if(a==='save-google'){saveGoogleConfiguration();return}if(a==='choose-google'){await startGoogleImport(el);return}if(a==='disconnect-google'){disconnectGoogle();googleStatus('Google access disconnected. Library entries remain on this device.');return}if(a==='review-batch'){try{startImportReview()}catch(err){alert(err.message)}return}if(a==='commit-batch'){try{await commitImportReview()}catch(err){alert('Import failed: '+err.message)}return}if(a==='cancel-batch'){importBatch=[];setView('import');return}
 if(a==='toggle-sidebar'){sidebarCollapsed=!sidebarCollapsed;writeSetting('atlas-sidebar',sidebarCollapsed?'collapsed':'');render();$('.sidebar-toggle')?.focus();return}
 if(a==='cycle-theme'||a.startsWith('theme-')){theme=a==='cycle-theme'?{system:'light',light:'dark',dark:'system'}[theme]:a.slice(6);writeSetting('atlas-theme',theme);render();(a==='cycle-theme'?$('[data-action="cycle-theme"]'):$(`[data-action="${a}"]`))?.focus();return}
 if(a==='persist'){const granted=await navigator.storage?.persist?.().catch(()=>false);await refreshStorage();msg(granted?'Local data is now protected from automatic clearing':'This browser did not grant persistent storage. Keep exporting backups.');return}
 if(a==='add'){pendingProvenance=null;editId=null;query='';view='editor';render();window.scrollTo(0,0)}else if(a==='add-condition'){activeCondition='';view='condition-editor';render()}else if(a==='edit-condition'){view='condition-editor';render()}else if(a==='all-regions')setView('library');else if(a==='library'||a==='import')setView(a);else if(a==='cancel')setView('library',activeRegion);else if(a==='edit'){view='editor';render();window.scrollTo(0,0)}else if(a==='favorite-detail'){const x=items.find(i=>i.id===editId);x.favorite=!x.favorite;await put('interventions',x);await reload()}else if(a==='delete'){const x=items.find(i=>i.id===editId);if(x&&confirm('Delete this intervention? You can restore it later from Settings → Recently deleted.')){const tx=db.transaction(['interventions','links','revisions'],'readwrite');addRevision(tx,'intervention',x,'Deleted',{links:linksFor(x.id)});tx.objectStore('interventions').delete(x.id);for(const l of links.filter(l=>l.interventionId===x.id))tx.objectStore('links').delete(l.id);await transactionDone(tx);await reload();setView('library')}}else if(a==='delete-condition'){const c=conditions.find(x=>x.name===activeCondition&&x.region===activeRegion);if(c&&confirm('Delete this condition and its protocol phases? Linked interventions remain in the library. You can restore it from Settings → Recently deleted.')){const tx=db.transaction(['conditions','links','phases','revisions'],'readwrite');addRevision(tx,'condition',c,'Deleted',{phases:phasesFor(c.id),links:links.filter(l=>l.conditionId===c.id)});tx.objectStore('conditions').delete(c.id);for(const ph of phasesFor(c.id))tx.objectStore('phases').delete(ph.id);for(const l of links.filter(l=>l.conditionId===c.id))tx.objectStore('links').delete(l.id);await transactionDone(tx);await reload();setView('library',activeRegion)}}else if(a==='export'){download(JSON.stringify(backupPayload({interventions:items,conditions,links,phases,collections,revisions}),null,2),'pt-atlas-backup-'+today()+'.json')}else if(a==='review-import'){const text=$('#importText').value.trim();if(!text){alert('Paste your document text first.');return}const title=$('#importTitle').value.trim()||text.split('\n').find(Boolean)?.slice(0,160)||'Imported note';const source=$('#importSource').value.trim();pendingProvenance={sourceTitle:title,...textFileMetadata,sourceFile:textFileMetadata.fileName||'',sourceModifiedAt:textFileMetadata.fileModifiedAt||'',importedAt:new Date().toISOString(),reviewStatus:'unreviewed'};editId=null;view='editor';render();$('#name').value=title;document.querySelector('[name="notes"]').value=text;document.querySelector('[name="source"]').value=source;notice='Review the extracted text and choose a region and condition before saving'}});
window.addEventListener('popstate',()=>{applyRoute();render();window.scrollTo(0,0)});
window.addEventListener('online',updateNetworkStatus);window.addEventListener('offline',updateNetworkStatus);
matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(theme==='system')applyTheme()});
(async()=>{try{db=await openDB();if(freshDatabase){for(const [region,name] of examples)await put('conditions',{id:uid(),region,name,overview:'',precautions:'',protocol:'',source:''})}applyRoute();await reload();refreshStorage();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineReady=true;updateNetworkStatus()}).catch(()=>{offlineReady=false;msg('Offline cache unavailable. Your library is still saved locally.')})}catch(err){document.querySelector('#app').innerHTML='<div class="fatal">Unable to initialize offline storage. Check browser permissions or private browsing settings. '+escapeHTML(err.message)+'</div>'}})();

function startImportReview(){
 const text=$('#importText').value,title=$('#importTitle').value.trim(),source=sourceURL($('#importSource').value);
 importBatch=documentDrafts(text,title,$('#splitSections').checked).map(draft=>({...draft,region:activeRegion||regions[0],condition:''}));
 importMetadata={documentTitle:title||importBatch[0].name,source,importedAt:new Date().toISOString(),...textFileMetadata};
 view='import-review';query='';render();
}
function importReview(){return `<div class="page-head">${kicker('Document review')}<h1>Review imported entries</h1><p class="lede small">Source text is preserved. No clinical classification or dosage has been inferred. Imported entries are marked unreviewed. Nothing is saved until you confirm.</p><p class="row-meta">Document: ${escapeHTML(importMetadata.documentTitle)} · Source: ${escapeHTML(importMetadata.source||'Not supplied')}</p></div><form id="batchForm" class="form">${importBatch.map((draft,index)=>`<section class="panel draft" data-draft="${index}"><div class="draft-head"><span class="num">${String(index+1).padStart(2,'0')}</span><p class="row-meta">Source: ${escapeHTML(draft.metadata?.documentTitle||importMetadata.documentTitle)} · ${escapeHTML(draft.metadata?.source||importMetadata.source||'Local file or pasted text')}</p></div><div class="field"><label>Entry title</label><input name="title-${index}" value="${escapeHTML(draft.name)}" required maxlength="160"></div><div class="two"><div class="field"><label>Body region</label><select name="region-${index}">${regions.map(region=>`<option ${region===draft.region?'selected':''}>${escapeHTML(region)}</option>`).join('')}</select></div><div class="field"><label>Condition (optional)</label><input name="condition-${index}" value="${escapeHTML(draft.condition)}"></div></div><div class="field"><label>Imported source text</label><textarea name="notes-${index}">${escapeHTML(draft.notes)}</textarea></div><div class="field"><label>Duplicate handling</label><select name="decision-${index}"><option value="skip">Skip if title and region already exist</option><option value="new">Create a separate entry</option><option value="merge">Append source text to the matching entry (confirmation required)</option></select></div><p class="row-meta">${duplicateEntries(draft,items).length} existing title/region matches before edits. Matches are checked again when saving.</p><label class="toggle"><input type="checkbox" name="include-${index}" checked><span>Include this entry</span></label></section>`).join('')}<div class="actions sticky-actions">${btn('Confirm import','commit-batch','primary')}${btn('Cancel import','cancel-batch','ghost')}</div></form>`}
async function commitImportReview(){
 const form=$('#batchForm');if(!form.reportValidity())return;
 const data=new FormData(form),planned=[],working=[...items];let skipped=0,merged=0;
 for(let index=0;index<importBatch.length;index++){
  if(!data.has('include-'+index)){skipped++;continue}
  const draft={name:String(data.get('title-'+index)),region:String(data.get('region-'+index)),condition:String(data.get('condition-'+index)),notes:String(data.get('notes-'+index))};
  const matches=duplicateEntries(draft,working),decision=data.get('decision-'+index);
  if(matches.length&&decision==='skip'){skipped++;continue}
  if(matches.length>1&&decision==='merge')throw Error('Multiple entries match “'+draft.name+'”. Choose create separate or skip.');
  const metadata=importBatch[index].metadata||importMetadata;
  let record=importRecord(draft,{...metadata,id:uid()});
  if(matches.length&&decision==='merge'){
   const old=matches[0];record={...old,notes:[old.notes,'Imported from '+(metadata.source||metadata.documentTitle)+' on '+metadata.importedAt,draft.notes].filter(Boolean).join('\n\n'),updated:record.updated,reviewStatus:'unreviewed',importHistory:JSON.stringify([...readImportHistory(old.importHistory),{...metadata}])};merged++;
   const prior=planned.findIndex(entry=>entry.id===old.id);if(prior!==-1)planned.splice(prior,1);
   working.splice(working.findIndex(entry=>entry.id===old.id),1);
  }
  planned.push(record);working.push(record);
 }
 if(!planned.length){msg('No entries to import. '+skipped+' skipped.');return}
 if(!confirm('Save '+planned.length+' entries? '+merged+' merges append imported text; '+skipped+' skipped. Existing structured fields are preserved.'))return;
 const tx=db.transaction('interventions','readwrite');for(const record of planned)tx.objectStore('interventions').put(record);await transactionDone(tx);
 importBatch=[];textFileMetadata={};view='library';await reload();msg('Imported '+planned.length+' entries locally; '+skipped+' skipped.');
}

function readImportHistory(value){try{const history=JSON.parse(value||'[]');return Array.isArray(history)?history.filter(entry=>entry&&typeof entry==='object'&&!Array.isArray(entry)):[]}catch{return []}}

function readGoogleConfiguration(){try{return JSON.parse(localStorage.getItem('atlas-google-config')||'{}')||{}}catch{return {}}}
function googleImportPanel(){const config=readGoogleConfiguration();return `<div class="panel"><h2>${icon('library',20)} Connect Google Docs</h2><p class="muted">Choose up to 10 Google Docs, including documents inside folders. Only files you select are authorized. Internet is required to connect and read documents; reviewed imports work offline afterward. Google libraries load only when you click the connection button.</p><details><summary>Google connection setup</summary><p class="muted">Enter public browser configuration from your Google Cloud project. Never enter a client secret. See GOOGLE_SETUP.md in the repository for API, consent, and origin setup.</p><div class="field"><label for="googleClientId">Web OAuth client ID</label><input id="googleClientId" value="${escapeHTML(config.clientId||'')}" autocomplete="off"></div><div class="field"><label for="googleApiKey">Picker API key</label><input id="googleApiKey" value="${escapeHTML(config.apiKey||'')}" autocomplete="off"></div><div class="field"><label for="googleProjectNumber">Google Cloud project number</label><input id="googleProjectNumber" value="${escapeHTML(config.projectNumber||'')}" inputmode="numeric"></div>${btn('Save Google setup','save-google','ghost')}</details><label class="toggle"><input type="checkbox" id="googleSplit"><span>Split Google Doc headings into entries</span></label><div class="actions">${btn('Choose Google Docs','choose-google','primary')}${btn('Disconnect Google','disconnect-google','ghost')}</div><p id="googleStatus" class="muted" role="status" aria-live="polite">${config.clientId?'Configuration saved in this browser.':'Google setup is required before connecting.'}</p><p class="row-meta">Access tokens stay in memory and expire. Disconnect revokes the current token; to remove all previously granted access, use your Google Account connections settings. PT Atlas only reads selected documents and never modifies them in Drive.</p></div>`}
function googleStatus(message){const status=$('#googleStatus');if(status)status.textContent=message;}
function saveGoogleConfiguration(){try{const config=validateGoogleConfig({clientId:$('#googleClientId').value,apiKey:$('#googleApiKey').value,projectNumber:$('#googleProjectNumber').value});disconnectGoogle();localStorage.setItem('atlas-google-config',JSON.stringify(config));googleStatus('Google setup saved in this browser. Choose Google Docs to continue.');}catch(error){googleStatus(error.message)}}
async function startGoogleImport(button){
 const container=button.closest('.panel');
 try{
  if(!navigator.onLine)throw Error('Google import needs an internet connection. Local files and your saved library remain available offline.');
  const config=validateGoogleConfig(readGoogleConfiguration());
  button.disabled=true;
  if(!googleReady()){googleStatus('Loading Google connection…');await prepareGoogle();if(container.isConnected)googleStatus('Google connection ready. Click Choose Google Docs again to sign in and open the picker.');return;}
  const split=$('#googleSplit').checked;googleStatus('Choose documents in Google. Selected content will open for review.');
  const documents=await chooseGoogleDocuments(config,{split});
  if(!container.isConnected)return;
  if(!documents.length){googleStatus('Selection cancelled. Nothing was imported.');return;}
  const drafts=documents.flatMap(document=>documentDrafts(document.text,document.metadata.documentTitle,document.split).map(draft=>({...draft,region:activeRegion||regions[0],condition:'',metadata:document.metadata})));
  if(drafts.length>100)throw Error('This selection creates more than 100 entries. Choose fewer documents or turn off heading splitting.');
  importBatch=drafts;importMetadata={documentTitle:documents.length+' selected Google Docs',source:''};view='import-review';query='';render();
 }catch(error){if(container.isConnected)googleStatus('Google import failed: '+error.message);}
 finally{if(button.isConnected)button.disabled=false;}
}

// ——— Knowledge management: condition links, protocol phases, collections, revisions ———
let pendingCollectionAdd=null;
const pad=n=>String(n).padStart(2,'0');
const colIds=col=>Array.isArray(col.interventionIds)?col.interventionIds:[];
const colItems=col=>colIds(col).map(id=>items.find(i=>i.id===id)).filter(Boolean);
function phaseCard(ph,i,count){const linked=(Array.isArray(ph.interventionIds)?ph.interventionIds:[]).map(id=>items.find(x=>x.id===id)).filter(Boolean);const name=escapeHTML(ph.name);return `<li class="phase"><span class="phase-num" aria-hidden="true">${i+1}</span><div class="phase-body"><div class="phase-title"><div>${kicker('Phase '+(i+1)+(ph.timeframe?' · '+escapeHTML(ph.timeframe):''))}<h3>${name}</h3></div><div class="phase-actions"><button type="button" class="iconbtn" data-action="phase-up" data-phase="${escapeHTML(ph.id)}" aria-label="Move ${name} earlier" ${i===0?'disabled':''}>${icon('up')}</button><button type="button" class="iconbtn" data-action="phase-down" data-phase="${escapeHTML(ph.id)}" aria-label="Move ${name} later" ${i===count-1?'disabled':''}>${icon('down')}</button><button type="button" class="btn ghost small" data-action="edit-phase" data-phase="${escapeHTML(ph.id)}" aria-label="Edit ${name}">${icon('edit',16)}Edit</button></div></div><dl class="phase-grid">${[['Objectives',ph.objectives],['Restrictions & precautions',ph.restrictions],['Criteria to progress',ph.criteria]].map(([t,v])=>`<div><dt>${t}</dt><dd>${v?`<span class="prose">${escapeHTML(v)}</span>`:'<span class="placeholder">Not recorded</span>'}</dd></div>`).join('')}</dl>${linked.length?`<div class="chips"><span class="row-meta">Interventions:</span>${linked.map(x=>`<button type="button" class="chip chip-link" data-open="${escapeHTML(x.id)}">${escapeHTML(x.name)}</button>`).join('')}</div>`:''}<p class="row-meta">Source: ${escapeHTML(ph.source||'Not recorded')}${ph.sourceDate?' · '+escapeHTML(ph.sourceDate):''}</p></div></li>`}
function phaseEditor(){const c=conditionById(phaseEdit?.conditionId);if(!c)return library();const ph=phases.find(p=>p.id===phaseEdit.phaseId)||{};const chosen=new Set(Array.isArray(ph.interventionIds)?ph.interventionIds:[]);const options=conditionEntries(c);return `<div class="page-head">${kicker(escapeHTML(c.name),c.region)}<h1>${ph.id?'Edit':'New'} protocol phase</h1><p class="lede small">Record each phase as written in the surgeon’s or provider’s protocol. PT Atlas never suggests timelines, restrictions or criteria.</p></div><form class="form" id="phaseForm"><fieldset class="panel"><legend>Phase</legend><div class="two">${field('name','Phase name *',ph.name,{type:'text',required:true,placeholder:'e.g. Phase 1'})}${field('timeframe','Timeframe',ph.timeframe,{type:'text',placeholder:'As written in your source'})}</div>${field('objectives','Objectives',ph.objectives)}${field('restrictions','Restrictions & precautions',ph.restrictions)}${field('criteria','Criteria to progress',ph.criteria)}</fieldset><fieldset class="panel"><legend>Linked interventions</legend>${options.length?`<div class="checks">${options.map(({x})=>`<label class="toggle"><input type="checkbox" name="interventionIds" value="${escapeHTML(x.id)}" ${chosen.has(x.id)?'checked':''}><span>${escapeHTML(x.name)}</span></label>`).join('')}</div>`:'<p class="placeholder">Interventions linked to this condition will appear here.</p>'}</fieldset><fieldset class="panel"><legend>Source</legend><div class="two">${field('source','Source / protocol name',ph.source,{type:'text',placeholder:'Provider protocol, guideline or citation'})}${field('sourceDate','Source date',ph.sourceDate,{type:'date'})}</div></fieldset><div class="actions sticky-actions"><button class="btn primary" type="submit">Save phase</button>${btn('Cancel','cancel-phase','ghost')}${ph.id?btn('Delete phase','delete-phase','danger','trash'):''}</div></form>`}
function showConditionTab(c,tab){view='condition';activeRegion=c.region;activeCondition=c.name;conditionTab=tab;phaseEdit=null}
async function savePhase(form){const c=conditionById(phaseEdit?.conditionId);if(!c)throw Error('Condition not found');const data=new FormData(form),old=phases.find(p=>p.id===phaseEdit.phaseId);const text=key=>String(data.get(key)||'');const list=phasesFor(c.id);const obj={...old,id:old?.id||uid(),conditionId:c.id,name:text('name').trim(),timeframe:text('timeframe'),objectives:text('objectives'),restrictions:text('restrictions'),criteria:text('criteria'),source:text('source'),sourceDate:text('sourceDate'),interventionIds:data.getAll('interventionIds').map(String),order:old?old.order:(list.length?Math.max(...list.map(p=>p.order||0))+1:0),updated:today()};if(!obj.name)throw Error('Each phase needs a name');await put('phases',obj);showConditionTab(c,'protocol');await reload();window.scrollTo(0,0);msg('Protocol phase saved locally')}
async function movePhase(id,delta){const ph=phases.find(p=>p.id===id);if(!ph)return;const list=phasesFor(ph.conditionId),i=list.indexOf(ph),j=i+delta;if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];const tx=db.transaction('phases','readwrite');list.forEach((p,order)=>tx.objectStore('phases').put({...p,order}));await transactionDone(tx);await reload();document.querySelector(`[data-action="phase-${delta<0?'up':'down'}"][data-phase="${CSS.escape(id)}"]`)?.focus()}
function historyPanel(entityId){const list=revisionsFor(entityId).filter(r=>r.summary!=='Deleted');if(!list.length)return '';return `<section class="panel history"><h2>${icon('history',20)} Revision history</h2><ol class="revlist">${list.map(r=>`<li><div><b>${r.summary==='Edited'?'Version before edit':escapeHTML(r.summary==='Before restore'?'Version before restore':r.summary)}</b><span class="row-meta">${fmtDate(r.at)}</span></div><button type="button" class="btn ghost small" data-action="restore-revision" data-rev="${escapeHTML(r.id)}">Restore</button></li>`).join('')}</ol><p class="row-meta">Earlier versions are kept on this device, up to ${REVISION_LIMIT} per entry, and included in backups.</p></section>`}
function linkPanel(x){const list=linksFor(x.id);return `<div class="panel glance"><h2>${icon('link',18)} Condition links</h2><p class="row-meta">Use the same intervention for other conditions, with details specific to each.</p>${list.length?`<ul class="linklist">${list.map(l=>{const c=conditionById(l.conditionId);return `<li><div class="linklist-head"><button type="button" class="linkish" data-condition="${escapeHTML(c.name)}" data-c-region="${escapeHTML(c.region)}">${escapeHTML(c.name)}</button><span class="linklist-actions"><button type="button" class="iconbtn" data-action="edit-link" data-link="${escapeHTML(l.id)}" aria-label="Edit link to ${escapeHTML(c.name)}">${icon('edit',16)}</button><button type="button" class="iconbtn" data-action="remove-link" data-link="${escapeHTML(l.id)}" aria-label="Unlink ${escapeHTML(c.name)}">${icon('trash',16)}</button></span></div><span class="row-meta">${escapeHTML(c.region)}</span>${linkContext(l)}</li>`}).join('')}</ul>`:''}${btn('Link to a condition','link-condition','ghost small','link')}</div>`}
function linkEditor(){const x=items.find(i=>i.id===linkEdit?.interventionId);if(!x)return library();const l=links.find(k=>k.id===linkEdit.linkId)||{};const taken=new Set(linksFor(x.id).filter(k=>k.id!==l.id).map(k=>k.conditionId));const groups=regions.map(r=>{const cs=conditions.filter(c=>c.region===r&&!taken.has(c.id)).sort((a,b)=>a.name.localeCompare(b.name));return cs.length?`<optgroup label="${escapeHTML(r)}">${cs.map(c=>`<option value="${escapeHTML(c.id)}" ${c.id===l.conditionId?'selected':''}>${escapeHTML(c.name)}</option>`).join('')}</optgroup>`:''}).join('');return `<div class="page-head">${kicker('Condition link',x.region)}<h1>${l.id?'Edit condition link':'Link to a condition'}</h1><p class="lede small">Attach “${escapeHTML(x.name)}” to a condition and record what is specific to it. The intervention itself is not duplicated.</p></div><form class="form" id="linkForm"><fieldset class="panel"><legend>Condition</legend><div class="field"><label>Linked condition *</label><select name="conditionId" required>${groups}</select></div></fieldset><fieldset class="panel"><legend>Condition-specific details</legend>${field('dosage','Condition-specific dosage',l.dosage,{hint:'From your source for this condition. PT Atlas never suggests defaults.'})}${field('restrictions','Condition-specific restrictions',l.restrictions)}${field('notes','Condition-specific notes',l.notes)}</fieldset><div class="actions sticky-actions"><button class="btn primary" type="submit">Save link</button>${btn('Cancel','cancel-link','ghost')}</div></form>`}
async function saveLink(form){const x=items.find(i=>i.id===linkEdit?.interventionId);if(!x)throw Error('Intervention not found');const data=new FormData(form),old=links.find(k=>k.id===linkEdit.linkId);const conditionId=String(data.get('conditionId')||'');if(!conditionById(conditionId))throw Error('Choose a condition');if(links.some(k=>k.id!==old?.id&&k.interventionId===x.id&&k.conditionId===conditionId))throw Error('This intervention is already linked to that condition');await put('links',{...old,id:old?.id||uid(),interventionId:x.id,conditionId,dosage:String(data.get('dosage')||''),restrictions:String(data.get('restrictions')||''),notes:String(data.get('notes')||''),updated:today()});linkEdit=null;editId=x.id;view='detail';await reload();window.scrollTo(0,0);msg('Condition link saved locally')}
function collectionPanel(x){const inside=collections.filter(col=>colIds(col).includes(x.id));const others=collections.filter(col=>!colIds(col).includes(x.id)).sort((a,b)=>a.name.localeCompare(b.name));return `<div class="panel glance"><h2>${icon('collection',18)} Collections</h2>${inside.length?`<div class="chips">${inside.map(col=>`<button type="button" class="chip chip-link" data-collection="${escapeHTML(col.id)}">${escapeHTML(col.name)}</button>`).join('')}</div>`:'<p class="row-meta">Not in any collection yet.</p>'}${others.length?`<div class="inline-form"><label class="sr-only" for="collectionPick">Collection</label><select id="collectionPick">${others.map(col=>`<option value="${escapeHTML(col.id)}">${escapeHTML(col.name)}</option>`).join('')}</select>${btn('Add to collection','add-to-collection','ghost small')}</div>`:''}<button type="button" class="link-cta" data-action="new-collection">New collection${icon('chevron',16)}</button></div>`}
function collectionsView(){const list=[...collections].sort((a,b)=>a.name.localeCompare(b.name));return `<div class="page-head">${kicker('Curate')}<h1>Collections</h1><p class="lede small">Group interventions into ordered sets for a clinic session, a home-program draft or a teaching outline, then print them.</p><div class="actions">${btn('New collection','new-collection','primary','plus')}</div></div>${list.length?`<div class="tiles">${list.map(col=>`<button class="tile" data-collection="${escapeHTML(col.id)}" style="--hue:#527DFF"><span class="tile-icon">${icon('collection',26)}</span><span class="tile-body"><h3>${escapeHTML(col.name)}</h3><span class="tile-meta">${plural(colItems(col).length,'intervention')}</span></span><span class="tile-arrow">${icon('arrow',18)}</span></button>`).join('')}</div>`:empty('No collections yet.','Create a collection, then add interventions from their detail pages.')}`}
function printBlock(x){const rows=[['Purpose',x.purpose],['Setup & positioning',x.setup],['Instructions',x.instructions],['Dosage',x.dosage],['Equipment',x.equipment],['Progressions & regressions',x.progressions],['Precautions',x.precautions]].filter(([,v])=>v);return rows.length?`<dl class="print-dl">${rows.map(([t,v])=>`<div><dt>${t}</dt><dd>${escapeHTML(v)}</dd></div>`).join('')}</dl>`:''}
function collectionPage(){const col=collections.find(c=>c.id===activeCollection);if(!col)return collectionsView();const list=colItems(col);return `<div class="page-head"><nav class="breadcrumb no-print" aria-label="Breadcrumb"><button data-nav="collections">Collections</button>${icon('chevron',14)}<span>${escapeHTML(col.name)}</span></nav>${kicker('Collection')}<h1>${escapeHTML(col.name)}</h1>${col.description?`<p class="lede small">${escapeHTML(col.description)}</p>`:''}<div class="actions no-print">${btn('Print','print','primary','print')}${btn('Edit collection','edit-collection','ghost','edit')}${btn('Delete collection','delete-collection','danger','trash')}</div></div>${list.length?`<ol class="collection-list">${list.map((x,i)=>`<li><span class="num">${pad(i+1)}</span><div class="collection-item"><div class="no-print">${itemCard(x)}</div><div class="print-only"><h3>${escapeHTML(x.name)}</h3><p class="row-meta">${escapeHTML(x.region)}${x.condition?' · '+escapeHTML(x.condition):''}</p>${printBlock(x)}</div></div><div class="order no-print"><button type="button" class="iconbtn" data-action="col-up" data-item="${escapeHTML(x.id)}" aria-label="Move ${escapeHTML(x.name)} up" ${i===0?'disabled':''}>${icon('up')}</button><button type="button" class="iconbtn" data-action="col-down" data-item="${escapeHTML(x.id)}" aria-label="Move ${escapeHTML(x.name)} down" ${i===list.length-1?'disabled':''}>${icon('down')}</button><button type="button" class="iconbtn" data-action="col-remove" data-item="${escapeHTML(x.id)}" aria-label="Remove ${escapeHTML(x.name)} from collection">${icon('trash')}</button></div></li>`).join('')}</ol>`:empty('This collection is empty.','Open any intervention and use “Add to collection”.')}<p class="fineprint print-only">Printed from PT Atlas on ${today()}. Content is user-entered; verify against patient-specific orders. Contains no patient information.</p>`}
function collectionEditor(){const col=collections.find(c=>c.id===collectionEditId)||{};return `<div class="page-head">${kicker('Curate')}<h1>${col.id?'Edit':'New'} collection</h1></div><form class="form" id="collectionForm"><fieldset class="panel"><legend>Collection</legend>${field('name','Collection name *',col.name,{type:'text',required:true,placeholder:'e.g. Hip strengthening set'})}${field('description','Description',col.description,{placeholder:'What this set is for (no patient information)'})}</fieldset><div class="actions sticky-actions"><button class="btn primary" type="submit">Save collection</button>${btn('Cancel','cancel-collection','ghost')}</div></form>`}
async function saveCollection(form){const data=new FormData(form),old=collections.find(c=>c.id===collectionEditId);const name=String(data.get('name')||'').trim();if(!name)throw Error('Name the collection');const ids=[...(old?colIds(old):[])];if(pendingCollectionAdd&&!ids.includes(pendingCollectionAdd)&&items.some(x=>x.id===pendingCollectionAdd))ids.push(pendingCollectionAdd);const obj={...old,id:old?.id||uid(),name,description:String(data.get('description')||''),interventionIds:ids,updated:today()};await put('collections',obj);pendingCollectionAdd=null;collectionEditId=null;activeCollection=obj.id;view='collection';await reload();window.scrollTo(0,0);msg('Collection saved locally')}
async function updateCollection(col,ids){await put('collections',{...col,interventionIds:ids,updated:today()});await reload()}
function recentlyDeleted(){const seen=new Set();const list=revisions.filter(r=>r.summary==='Deleted'&&!(r.entityType==='condition'?conditions:items).some(x=>x.id===r.entityId)).sort((a,b)=>b.at.localeCompare(a.at)).filter(r=>!seen.has(r.entityId)&&seen.add(r.entityId));return `<section class="panel"><h2>Recently deleted</h2><p class="muted">Deleted interventions and conditions can be restored with their condition links and protocol phases.</p>${list.length?`<ul class="revlist">${list.map(r=>`<li><div><b>${escapeHTML(r.entityName||'Untitled')}</b><span class="row-meta">${r.entityType==='condition'?'Condition':'Intervention'} · deleted ${fmtDate(r.at)}</span></div><button type="button" class="btn ghost small" data-action="restore-revision" data-rev="${escapeHTML(r.id)}" aria-label="Restore ${escapeHTML(r.entityName||'entry')}">Restore</button></li>`).join('')}</ul>`:'<p class="row-meta">Nothing deleted recently.</p>'}</section>`}
async function restoreRevision(id){
 const r=revisions.find(v=>v.id===id),snap=r&&readSnapshot(r);if(!snap)throw Error('This version cannot be restored.');
 const isCondition=r.entityType==='condition',store=isCondition?'conditions':'interventions',record=snap.record;
 if(typeof record.id!=='string'||typeof record.name!=='string'||!regions.includes(record.region))throw Error('This version cannot be restored.');
 const current=(isCondition?conditions:items).find(x=>x.id===record.id);
 if(isCondition&&conditions.some(c=>c.id!==record.id&&c.name===record.name&&c.region===record.region))throw Error('Another condition in this region already uses that name. Rename it first.');
 if(!confirm(current?`Restore this earlier version of “${record.name}”? The current version stays in history.`:`Restore “${record.name}”?`))return;
 const tx=db.transaction(['interventions','conditions','links','phases','revisions'],'readwrite');
 if(current)addRevision(tx,r.entityType,current,'Before restore');
 tx.objectStore(store).put({...record,updated:today()});
 if(isCondition&&current&&(current.name!==record.name||current.region!==record.region))for(const item of items.filter(i=>i.region===current.region&&i.condition===current.name))tx.objectStore('interventions').put({...item,region:record.region,condition:record.name});
 for(const l of Array.isArray(snap.links)?snap.links:[])if(l&&typeof l.id==='string'&&typeof l.interventionId==='string'&&typeof l.conditionId==='string')tx.objectStore('links').put(l);
 for(const ph of Array.isArray(snap.phases)?snap.phases:[])if(ph&&typeof ph.id==='string'&&typeof ph.conditionId==='string')tx.objectStore('phases').put(ph);
 await transactionDone(tx);
 if(isCondition){view='condition';activeRegion=record.region;activeCondition=record.name;conditionTab='overview'}else{view='detail';editId=record.id}
 query='';await reload();window.scrollTo(0,0);msg('Restored “'+record.name+'”');
}
async function knowledgeAction(a,el){
 const x=items.find(i=>i.id===editId),c=conditions.find(k=>k.name===activeCondition&&k.region===activeRegion),col=collections.find(k=>k.id===activeCollection);
 switch(a){
  case 'review-queue':setView('library');filters.status=items.some(i=>statusOf(i)==='unreviewed')||!items.some(i=>reviewDue(i))?'unreviewed':'due';render();return true;
  case 'collections':setView('collections');return true;
  case 'restore-revision':await restoreRevision(el.dataset.rev);return true;
  case 'link-condition':linkEdit={interventionId:editId,linkId:null};view='link-editor';render();window.scrollTo(0,0);return true;
  case 'edit-link':linkEdit={interventionId:editId,linkId:el.dataset.link};view='link-editor';render();window.scrollTo(0,0);return true;
  case 'cancel-link':linkEdit=null;view='detail';render();return true;
  case 'remove-link':{const l=links.find(k=>k.id===el.dataset.link);if(l&&confirm('Remove this condition link? The intervention and condition are kept.')){await remove('links',l.id);await reload();msg('Condition link removed')}return true}
  case 'add-phase':if(c){phaseEdit={conditionId:c.id,phaseId:null};view='phase-editor';render();window.scrollTo(0,0)}return true;
  case 'edit-phase':if(c){phaseEdit={conditionId:c.id,phaseId:el.dataset.phase};view='phase-editor';render();window.scrollTo(0,0)}return true;
  case 'cancel-phase':{const pc=conditionById(phaseEdit?.conditionId);if(pc)showConditionTab(pc,'protocol');render();return true}
  case 'delete-phase':{const pc=conditionById(phaseEdit?.conditionId);if(pc&&confirm('Delete this protocol phase?')){await remove('phases',phaseEdit.phaseId);showConditionTab(pc,'protocol');await reload();msg('Protocol phase deleted')}return true}
  case 'phase-up':case 'phase-down':await movePhase(el.dataset.phase,a==='phase-up'?-1:1);return true;
  case 'new-collection':pendingCollectionAdd=view==='detail'?editId:null;collectionEditId=null;view='collection-editor';render();window.scrollTo(0,0);return true;
  case 'edit-collection':collectionEditId=activeCollection;pendingCollectionAdd=null;view='collection-editor';render();return true;
  case 'cancel-collection':{const back=pendingCollectionAdd;pendingCollectionAdd=null;if(back){editId=back;view='detail'}else view=collectionEditId?'collection':'collections';collectionEditId=null;render();return true}
  case 'delete-collection':if(col&&confirm('Delete this collection? Its interventions stay in your library.')){await remove('collections',col.id);setView('collections');await reload();msg('Collection deleted')}return true;
  case 'add-to-collection':{const target=collections.find(k=>k.id===$('#collectionPick')?.value);if(target&&x){await updateCollection(target,[...colIds(target),x.id]);msg('Added to '+target.name)}return true}
  case 'col-up':case 'col-down':case 'col-remove':{if(!col)return true;const ids=colIds(col).filter(id=>items.some(i=>i.id===id)),i=ids.indexOf(el.dataset.item);if(i<0)return true;if(a==='col-remove')ids.splice(i,1);else{const j=i+(a==='col-up'?-1:1);if(j<0||j>=ids.length)return true;[ids[i],ids[j]]=[ids[j],ids[i]]}await updateCollection(col,ids);if(a!=='col-remove')document.querySelector(`[data-action="${a}"][data-item="${CSS.escape(el.dataset.item)}"]`)?.focus();return true}
  case 'print':window.print();return true;
 }
 return false;
}
